def count_duplic(lst):
    if not lst:
        return ([], [])

    values = []
    counts = []

    current = lst[0]
    count = 1

    for i in range(1, len(lst)):
        if lst[i] == current:
            count += 1
        else:
            values.append(current)
            counts.append(count)
            current = lst[i]
            count = 1

    values.append(current)
    counts.append(count)

    return (values, counts)
```

